alter table teacher_course_assignments add column if not exists section_capacity smallint check(section_capacity is null or section_capacity>0);
create table if not exists student_sectioning_issues(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),student_id uuid not null references students(id) on delete cascade,request_id uuid references student_course_requests(id) on delete cascade,code text not null,detail text,created_at timestamptz not null default now());
create index if not exists idx_student_sectioning_issues on student_sectioning_issues(institution_code,student_id,created_at desc);alter table student_sectioning_issues enable row level security;
drop policy if exists student_sectioning_issues_read on student_sectioning_issues;create policy student_sectioning_issues_read on student_sectioning_issues for select to authenticated using(tenant_row_allowed(institution_code));drop policy if exists student_sectioning_issues_manage on student_sectioning_issues;create policy student_sectioning_issues_manage on student_sectioning_issues for all to authenticated using((has_permission('schedule.generate') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.generate') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
create or replace function section_students_batch_v1(p_replace_solver boolean default true) returns jsonb language plpgsql security definer set search_path=public as $$declare q record;a uuid;assigned int:=0;unassigned int:=0;begin if not(is_manager_or_admin() or has_permission('schedule.generate')) then raise exception 'NOT_AUTHORIZED';end if;if p_replace_solver then delete from student_schedule_enrollments where institution_code=current_tenant_code() and source='solver' and not locked;end if;delete from student_sectioning_issues where institution_code=current_tenant_code();for q in select r.*,s.id sid from student_course_requests r join students s on s.id=r.student_id and s.active where r.active and r.institution_code=current_tenant_code() order by s.id,case r.request_kind when 'PRIMARY' then 0 when 'ALTERNATIVE' then 1 else 2 end,r.priority,r.id loop if q.alternative_group is not null and exists(select 1 from student_course_requests rr join student_schedule_enrollments e on e.student_id=q.sid and e.active join teacher_course_assignments ta on ta.id=e.teacher_assignment_id join class_course_requirements cr on cr.id=ta.class_course_requirement_id where rr.student_id=q.sid and rr.active and rr.alternative_group=q.alternative_group and cr.course_id=rr.course_id) then continue;end if;select x.assignment_id into a from(select ta.id assignment_id,coalesce(ta.section_capacity,(select min(c.capacity) from teacher_schedule ts join classrooms c on c.id=ts.classroom_id where ts.active and ts.teacher_assignment_id=ta.id)) cap,(select count(*) from student_schedule_enrollments e where e.active and e.teacher_assignment_id=ta.id) load,coalesce((select sum(case f.mode when 'MEDIUM' then f.weight*10 when 'SOFT' then f.weight else 0 end) from student_free_time_requests f join teacher_schedule ts on ts.teacher_assignment_id=ta.id and ts.active where f.active and f.student_id=q.sid and f.weekday=ts.weekday and ts.period=any(f.periods)),0) pref from teacher_course_assignments ta join class_course_requirements cr on cr.id=ta.class_course_requirement_id where ta.institution_code=current_tenant_code() and cr.course_id=q.course_id and exists(select 1 from teacher_schedule ts where ts.active and ts.teacher_assignment_id=ta.id) and not exists(select 1 from student_free_time_requests f join teacher_schedule ts on ts.teacher_assignment_id=ta.id and ts.active where f.active and f.student_id=q.sid and f.mode='HARD' and f.weekday=ts.weekday and ts.period=any(f.periods)) and (q.allow_overlap or not exists(select 1 from student_schedule_enrollments e join teacher_schedule old on old.teacher_assignment_id=e.teacher_assignment_id and old.active join teacher_schedule nw on nw.teacher_assignment_id=ta.id and nw.active where e.student_id=q.sid and e.active and old.weekday=nw.weekday and old.period=nw.period)))x where x.cap is not null and x.load<x.cap order by x.pref,x.load,x.cap desc,x.assignment_id limit 1;if a is null then insert into student_sectioning_issues(student_id,request_id,code,detail) values(q.sid,q.id,'NO_FEASIBLE_SECTION','Kapasite, çakışma veya HARD serbest-zaman kuralı nedeniyle uygun section bulunamadı.');unassigned:=unassigned+1;else insert into student_schedule_enrollments(student_id,teacher_assignment_id,source,institution_code) values(q.sid,a,'solver',current_tenant_code()) on conflict(institution_code,student_id,teacher_assignment_id) do update set active=true,source='solver',updated_at=now();assigned:=assigned+1;end if;end loop;return jsonb_build_object('assigned',assigned,'unassigned',unassigned);end$$;